from datetime import date

import pytest

from app.engine import EngineConfig, classify, score_trades
from app.engine.types import CounterpartyRef, ReferenceData

BUSINESS_DATE = date.fromisoformat('2026-09-28')
BASE = {'trade_id': 'EC000',
 'trade_type': 'BUY',
 'symbol': 'AAPL',
 'quantity': '1000',
 'price': '100.00',
 'counterparty': 'UBS',
 'trade_date': '10/5/2026',
 'settlement_date': '10/7/2026',
 'account_id': 'ACC1000',
 'ssi_matched': 'YES',
 'currency_matched': 'YES',
 'trader_name': 'Wei Zhang'}
HEADERS = ['Trade ID',
 'Trade Type',
 'Symbol',
 'Quantity',
 'Price',
 'Counterparty',
 'Trade Date',
 'Settlement Date',
 'Account ID',
 'SSI Matched',
 'Currency Matched',
 'Trader Name']
KEYS = ['trade_id',
 'trade_type',
 'symbol',
 'quantity',
 'price',
 'counterparty',
 'trade_date',
 'settlement_date',
 'account_id',
 'ssi_matched',
 'currency_matched',
 'trader_name']


def refs():
    tiers = {"UBS": 1, "State Street": 2, "Vanguard": 3, "BlackRock": 4}
    return ReferenceData(
        symbols={"AAPL", "ISRG1"},
        counterparties={n.lower(): CounterpartyRef(n, t, f"Tier{t}", 0, 0, 0.0) for n, t in tiers.items()},
        accounts={"ACC1000": True, "ACC1011": False, "ACC1063": False, "ACC1093": False},
        symbol_stats={},
    )


def trade(override):
    t = {**BASE, **override}
    return {h: t[k] for h, k in zip(HEADERS, KEYS)}


